WITH base AS (SELECT * FROM customers WHERE credit_limit < 11300 AND (signup_date > '2025-01-01' OR segment IN ('Corporate', 'SMB'))), summary AS (SELECT DATE_FORMAT(signup_date, 'yyyy-MM') signup_month, segment, COUNT(DISTINCT credit_limit) unique_countrys FROM base GROUP BY DATE_FORMAT(signup_date, 'yyyy-MM'), segment) SELECT signup_month, segment FROM summary WHERE unique_countrys > 5 ORDER BY segment DESC
